import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A member of a pool with their share percent (two decimals): a person (memberPool null), retired when the person has
 *  a retirement date set, or another pool (memberPool its name, person 0); the membership's from-date and to-date (''
 *  when none) and whether they include the sheet's today (a member outside them is left out entirely); and their cut
 *  of the pool's pot (two decimals), '' when the pool is not balanced, has no pot or has only retired members, or the member is
 *  outside their dates. A pool in none has the sheet's pot; a pool in another has its cut there. */
export type PoolMember = {
  person: number;
  memberPool: string | null;
  name: string;
  share: string;
  retired: boolean;
  from: string;
  to: string;
  current: boolean;
  cut: string;
};

/** A pool: its members, the total of their shares (a retired member's counting as given, one outside their dates left out), and whether that is 100.00. */
export type Pool = { name: string; members: PoolMember[]; totalShare: string; balanced: boolean };

export const poolsKey = (sheet: string) => ['pools', sheet] as const;

export const poolsPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/pools`;

export const poolMembersPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/pool-members`;

/** The sheet's pools, in the order added. */
export function usePools(sheet: string) {
  return useQuery({
    queryKey: poolsKey(sheet),
    queryFn: () => getJson<Pool[]>(poolsPath(sheet)),
  });
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { byUser } from '../session/session';
import { usePeople } from '../people/people';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { poolMembersPath, poolsKey, poolsPath, usePools, type Pool } from './pools';

// One pool's row: its members with their shares and cuts of the pot, its total share and whether it is balanced, and a form that adds
// a member chosen from the sheet's people or its other pools (pool:<name>).
function PoolRow({ sheet, user, pool, pools }: { sheet: string; user: string; pool: Pool; pools: Pool[] }) {
  const queryClient = useQueryClient();
  const { data: people = [] } = usePeople(sheet);
  // A person's id, or pool:<name> for another pool.
  const [member, setMember] = useState('');
  const [share, setShare] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');

  const add = useMutation({
    mutationFn: (body: {
      pool: string;
      person: number | null;
      memberPool: string | null;
      share: string;
      from: string;
      to: string;
    }) =>
      postJson<Pool[]>(byUser(poolMembersPath(sheet), user), body),
    onSuccess: (updated) => {
      queryClient.setQueryData(poolsKey(sheet), updated);
      setMember('');
      setShare('');
      setFrom('');
      setTo('');
    },
  });
  const send = useSubmitOnce(add);

  const submit = (e: FormEvent) => {
    e.preventDefault();
    // The server refuses a person already in the pool, a bad share, or a pool already in one, that would contain
    // itself, or would make a chain more than three deep, and a to-date before the from-date.
    const memberPool = member.startsWith('pool:') ? member.slice('pool:'.length) : null;
    const person = memberPool !== null || member === '' ? null : Number(member);
    send({ pool: pool.name, person, memberPool, share, from, to });
  };

  return (
    <li data-testid={`pool-row-${pool.name}`}>
      <strong>{pool.name}</strong> — total share <span data-testid="pool-total-share">{pool.totalShare}</span>,
      balanced <span data-testid="pool-balanced">{pool.balanced ? 'yes' : 'no'}</span>
      <ul>
        {pool.members.map((m) => (
          <li
            key={m.memberPool !== null ? `pool:${m.memberPool}` : m.person}
            data-testid={`pool-member-${pool.name}-${m.memberPool !== null ? `pool-${m.memberPool}` : m.person}`}
          >
            {m.name} <span data-testid="pool-share">{m.share}</span>%{m.retired ? ' (retired)' : ''}
            {m.from || m.to ? ` (${m.from || '…'} to ${m.to || '…'})` : ''}
            {m.current ? '' : ' (not current)'}, cut{' '}
            <span data-testid="pool-cut">{m.cut}</span>
          </li>
        ))}
      </ul>
      <form onSubmit={submit}>
        <select
          data-testid="pool-member-select"
          value={member}
          onChange={(e) => {
            setMember(e.target.value);
            add.reset();
          }}
        >
          <option value="">Choose a member</option>
          {people.map((p) => (
            <option key={p.id} value={String(p.id)}>
              {p.name}
            </option>
          ))}
          {pools.map((p) => (
            <option key={`pool:${p.name}`} value={`pool:${p.name}`}>
              {`pool:${p.name}`}
            </option>
          ))}
        </select>{' '}
        <label>
          Share %{' '}
          <input
            data-testid="pool-member-share"
            value={share}
            onChange={(e) => {
              setShare(e.target.value);
              add.reset();
            }}
          />
        </label>{' '}
        <label>
          From{' '}
          <input
            type="date"
            data-testid="pool-member-from"
            value={from}
            onChange={(e) => {
              setFrom(e.target.value);
              add.reset();
            }}
          />
        </label>{' '}
        <label>
          To{' '}
          <input
            type="date"
            data-testid="pool-member-to"
            value={to}
            onChange={(e) => {
              setTo(e.target.value);
              add.reset();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="pool-member-add" disabled={add.isPending}>
          Add member
        </button>
        {add.isError && (
          <span data-testid="pool-error" role="alert">
            {' '}A member must not already be in the pool, and a share has two decimals, above 0.00 and at most
            100.00. A pool may be in at most one pool, never contain itself, and a chain of pools is at most three
            deep. A membership's to-date may not be before its from-date.
          </span>
        )}
      </form>
    </li>
  );
}

// The sheet's pools, and a form that adds one.
function Pools({ sheet, user }: { sheet: string; user: string }) {
  const queryClient = useQueryClient();
  const { data: pools = [] } = usePools(sheet);
  const [name, setName] = useState('');

  const add = useMutation({
    mutationFn: (body: { name: string }) => postJson<Pool[]>(byUser(poolsPath(sheet), user), body),
    onSuccess: (updated) => {
      queryClient.setQueryData(poolsKey(sheet), updated);
      setName('');
    },
  });
  const send = useSubmitOnce(add);

  const change = (next: string) => {
    setName(next);
    add.reset();
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    // The server refuses a blank name or one already a pool.
    send({ name });
  };

  return (
    <section>
      <h2>Pools</h2>
      <form onSubmit={submit}>
        <label>
          Name <input data-testid="pool-form-name" value={name} onChange={(e) => change(e.target.value)} />
        </label>{' '}
        <button type="submit" data-testid="pool-form-submit" disabled={add.isPending}>
          Add pool
        </button>
        {add.isError && (
          <span data-testid="pool-form-error" role="alert">
            {' '}A pool's name must not be blank nor already a pool.
          </span>
        )}
      </form>
      <ul>
        {pools.map((p) => (
          <PoolRow key={p.name} sheet={sheet} user={user} pool={p} pools={pools} />
        ))}
      </ul>
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 9.8, Component: Pools });
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { usePeople } from './people';
import { useSheetToday } from '../sheet/sheet';
import { showDue, useRates } from '../rates/rates';
import { useCapCents, useFloorCents } from '../settings/settings';
import { personDueCents, useClaims, useLate } from '../claims/claims';

// A CSV value: wrapped in double quotes (any quote inside doubled) when it holds a comma, a quote or a line break.
const csvValue = (v: string) => (/[",\r\n]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v);

// The button that downloads the people as CSV: everyone in list order, retired people included, with the grade in
// force on the sheet's today, the retired-from date (or nothing) and the due-total as their row shows it.
function ExportPeople({ sheet }: { sheet: string; user: string }) {
  const { data: people = [] } = usePeople(sheet);
  const { data: claims = [] } = useClaims(sheet);
  const { data: rates = [] } = useRates(sheet);
  const today = useSheetToday(sheet);
  const floor = useFloorCents(sheet);
  const cap = useCapCents(sheet);
  const late = useLate(sheet);

  const download = () => {
    const lines = [
      'name,grade,retired-from,due-total',
      ...people.map((p) =>
        [p.name, p.grade, p.retiredFrom ?? '', showDue(personDueCents(claims, rates, p, today, floor, late, cap))]
          .map(csvValue)
          .join(','),
      ),
    ];
    const url = URL.createObjectURL(new Blob([lines.map((l) => `${l}\n`).join('')], { type: 'text/csv' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = `people-${sheet}.csv`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };

  return (
    <p>
      <button type="button" data-testid="export-people" onClick={download}>
        Export people (CSV)
      </button>
    </p>
  );
}

export const contribution = SheetPanels.fill({ order: 11, Component: ExportPeople });
import { PersonColumnHeaders, PersonColumns } from '../../slots/defs/personRow';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import type { Person } from '../people/people';
import { hundredths, twoDecimals } from '../rates/rates';
import { usePools, type Pool } from './pools';

/** A person's cut total in hundredths: their cuts across every pool they are a member of, a pool that shows no cut
 *  adding nothing. */
function personCutCents(pools: Pool[], personId: number): bigint {
  let cents = 0n;
  for (const pool of pools) {
    for (const m of pool.members) {
      if (m.memberPool === null && m.person === personId && m.cut !== '') cents += hundredths(m.cut);
    }
  }
  return cents;
}

/** The sheet's cut total in hundredths: every person's cut total added up. */
function sheetCutCents(pools: Pool[]): bigint {
  let cents = 0n;
  for (const pool of pools) {
    for (const m of pool.members) {
      if (m.memberPool === null && m.cut !== '') cents += hundredths(m.cut);
    }
  }
  return cents;
}

function CutTotalHeader() {
  return <th>Cut total</th>;
}

function PersonCutTotal({ sheet, person }: { sheet: string; user: string; person: Person }) {
  const { data: pools = [] } = usePools(sheet);
  return <td data-testid="person-cut-total">{twoDecimals(personCutCents(pools, person.id))}</td>;
}

function SheetCutTotal({ sheet }: { sheet: string; user: string }) {
  const { data: pools = [] } = usePools(sheet);
  return (
    <p>
      Cut total: <strong data-testid="rollup-cut-total">{twoDecimals(sheetCutCents(pools))}</strong>
    </p>
  );
}

export const contributions = [
  PersonColumnHeaders.fill({ order: 9.8, Component: CutTotalHeader }),
  PersonColumns.fill({ order: 9.8, Component: PersonCutTotal }),
  SheetPanels.fill({ order: 20.1, Component: SheetCutTotal }),
];

